<?php require_once __DIR__ . '/../bootstrap.php'; $user=require_auth(); $where=[];$params=[]; if($user['role']!=='admin'){ $where[]='l.user_id=?';$params[]=$user['id']; } elseif(isset($_GET['user_id'])&&$_GET['user_id']!==''){$where[]='l.user_id=?';$params[]=(int)$_GET['user_id'];} foreach(['status','category'] as $key){if(!empty($_GET[$key])){$where[]="l.$key=?";$params[]=$_GET[$key];}} if(!empty($_GET['search'])){$where[]='(l.title LIKE ? OR l.activity LIKE ? OR l.location LIKE ? OR u.full_name LIKE ?)';$term='%'.$_GET['search'].'%';array_push($params,$term,$term,$term,$term);} $sql='SELECT l.*,u.full_name,u.username FROM log_entries l JOIN users u ON u.id=l.user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY l.log_date DESC,l.created_at DESC LIMIT 100';$stmt=$pdo->prepare($sql);$stmt->execute($params);respond(true,'',['logs'=>$stmt->fetchAll()]);
